rep("\n.mur .ed-part{", r"""
/* (b4) la préparation du cahier de textes (7.0 ter) : la poignée, la zone de préparation sous la diapo, les notes réduites, le volet réduit, le pas à pas */
.poignee-mur{display:none;height:12px;cursor:row-resize;align-items:center;justify-content:center}.poignee-mur span{width:120px;height:6px;border-radius:3px;background:var(--bord2)}.poignee-mur:hover span{background:var(--or)}.corps.prep .poignee-mur{display:flex}
.corps.prep .volet .vig .mini{display:none}.corps.prep .volet .vig{padding:2px 4px}.corps.prep .volet .vig .n{font-size:.9rem}
.notes.reduites{flex:0 0 26px;min-height:26px;height:26px;overflow:hidden;padding:3px 12px;font-size:.75rem;color:var(--sourd)}.notes.reduites h5{margin:0;display:inline}.notes.reduites > *:not(h5){display:none}
.prep{background:var(--carte);border:1px solid var(--or);border-radius:10px;padding:8px 12px;flex:1 1 auto;min-height:0;overflow:auto}
.pp{display:grid;grid-template-columns:1fr 250px;gap:14px}.pp-tete{display:flex;justify-content:space-between;align-items:center;gap:8px;margin-bottom:4px}.pp-tete b{color:var(--or)}.pp-fil{display:flex;gap:4px;margin:4px 0 8px}.pp-fil span{flex:1;height:6px;border-radius:3px;background:var(--bord2)}.pp-fil span.ok{background:var(--joue)}.pp-fil span.ici{background:var(--or)}.pp-quoi{font-size:.9rem;color:var(--texte2);margin-bottom:6px}.pp-nav{display:flex;justify-content:space-between;gap:8px;margin-top:10px}.pp-liste{font-size:.8rem;color:var(--texte2);line-height:1.5;border-left:1px dotted var(--bord2);padding-left:12px}.pp-liste .ctl-l{cursor:pointer}.pp-liste .ctl-l.ok{color:var(--joue)}.pp-liste .ctl-l.ici,.pp-liste .sec.ouverte .ctl-l{color:var(--or);font-weight:600}.pp-liste .okr{display:block;font-weight:400;color:var(--joue);font-size:.75rem}.pp-attente{background:#2a2114;border:1px solid #c99a4e;border-radius:8px;padding:6px 10px;color:#e0c48c;font-size:.88rem;margin:4px 0 8px}
#fin .pp{grid-template-columns:1fr}#fin .pp-liste{border-left:0;padding-left:0;border-top:1px dotted var(--bord2);padding-top:6px;margin-top:8px}
.mur .ed-part{""")
