i=s.index("function sequenceHtml(h, cloture, restantes){"); j=s.index("function ouvrirFin(cloture){")
new_seq = r"""function sequenceHtml(h, cloture, restantes){ /* (b4) 7.0 bis/ter : le pas à pas — une étape à la fois, ce qu'il faut y faire, ses contrôles, deux boutons ; le fil ; la liste des sept, cliquable */
  const tmp = document.createElement('div'); tmp.innerHTML = h; const q = sel => tmp.querySelector(sel); const out = n => (n ? n.outerHTML : '');
  const echLabel = tmp.querySelector('#f-ech') ? tmp.querySelector('#f-ech').closest('label') : null; if (echLabel) echLabel.remove(); const travaux = tmp.querySelectorAll('.travail'); const travail = travaux[0]; const avant = tmp.querySelector('#f-mot') ? tmp.querySelector('#f-mot').closest('.travail') : null; const rangee = q('.rangee'); const h3prevu = tmp.querySelector('h3'); const barre = q('.barre-fin'); tmp.querySelectorAll('[data-finvue]').forEach(x => x.parentElement.remove());
  S.finSection = S.finSection || 1; S.finFaites = S.finFaites || {}; const ctl = controleCahier(restantes); const E = ctl.etapes; const n = S.finSection; const et = E[n - 1]; const hh = S.heure; const nbF = E.filter(e => e.ok && e.n < 7).length;
  const TITRES = { 1: 'l\'échéance', 2: 'ce qui reste', 3: 'le travail à faire', 4: 'le récit relu', 5: 'avant de clore', 6: 'copier pour École Directe', 7: 'clore l\'heure' };
  const resume = { 1: S.echeance ? '✔ ' + esc((DATA.classe.prochaines.find(x => x.iso === S.echeance) || {}).l || S.echeance) : ((S.finFaites || {})[1] ? '✔ sans échéance' : ''), 2: (restantes || []).length ? (restantes || []).map(x => (S.decisions[x.a.id] || {}).choix).filter(Boolean).map(c => ({ suivante: 'à l\'heure suivante', terminer: 'à la maison', preparer: 'à préparer', reserve: 'en réserve', nonfait: 'non fait', reporter: 'reportée', pastemps: 'à la maison', passee: 'passée' }[c] || c)).join(', ') : 'rien ne restait', 3: (S.rienProchaine || {})[hh] ? 'rien pour la prochaine fois' : esc((texteTravail() || '').trim().slice(0, 50)) + '…', 4: (S.recitVersion || {})[hh] === 'moi' ? 'ma version' : 'relu', 5: 'notes, versements, mot aux absents', 6: 'copié (contenu et travail)', 7: '' };
  const QUOI = { 1: 'Prenez vos agendas pour le… — la date part au tableau, dans le cahier de textes. Choisis-la, ou dis « sans échéance ».', 2: 'Ce qui était prévu pour cette heure et n\'a pas été fait : une décision par activité (à l\'heure suivante, à la maison, à préparer, en réserve, non fait).', 3: 'Ce que les élèves auront à faire. Déjà là : ce que la trame prévoyait, les notions cochées, l\'activité à finir à la maison si tu l\'as décidé. Ajoute ce que tu veux, ou dis qu\'il n\'y a rien d\'autre.', 4: 'Parcours le récit une fois (dans le cahier, onglet Contenus, ou dans la relecture) ; l\'étape se coche quand tu as atteint le bout du récit final, ou d\'un clic.', 5: 'Les notes à garder, ce qui se verse dans la trame, le mot aux absents.', 6: 'Copie, puis colle dans École Directe : d\'abord le contenu de séance, puis le travail à faire.', 7: 'Clore ferme l\'heure : le journal, le récit, le travail à faire et le mot des absents sont enregistrés pour cette classe.' };
  const corps = {};
  corps[1] = `${out(echLabel)}<div style="margin-top:6px"><button class="btn" id="f-sans-ech" title="Pas d\'échéance donnée : le cahier dira « la prochaine fois »">Sans échéance</button></div>`;
  corps[2] = `${out(h3prevu)}${out(rangee)}`;
  corps[3] = `${out(travail)}<div style="margin-top:8px;display:flex;gap:8px;flex-wrap:wrap"><button class="btn" id="f-rien" title="Rien à faire pour la prochaine fois : l\'étape est faite, en connaissance de cause">${(S.rienProchaine || {})[hh] ? '✔ rien pour la prochaine fois' : 'Rien d\'autre pour la prochaine fois'}</button><button class="btn" id="f-vers-travail" title="Va au champ du travail à faire, dans la diapo du cahier">Écrire dans le cahier ▸</button></div>`;
  const recitFinal = !!S.close || (ecran().role === 'fin' && !S.preparation); corps[4] = `${recitFinal ? '' : `<div class="pp-attente">Il est ${hhmm()} : <b>le récit se complète jusqu\'à la fin de l\'heure</b> — ce que tu lis maintenant n\'est pas encore ce qui partira. Tu peux le lire et le retoucher (ma version), l\'étape ne se cochera qu\'une fois l\'heure jouée et le récit relu à la fin.</div>`}<div style="display:flex;gap:8px;flex-wrap:wrap"><button class="btn" id="f-vers-recit" title="Va au récit dans la diapo du cahier">Lire dans le cahier ▸</button><button class="btn" id="f-relu" ${recitFinal ? '' : 'disabled '}title="${recitFinal ? 'Tu l\'as relu : l\'étape est faite' : 'À relire à la fin de l\'heure : le récit n\'est pas fini'}">${et && E[3].ok ? '✔ relu' : (recitFinal ? 'Relu' : 'Relu (à la fin de l\'heure)')}</button></div>`;
  corps[5] = cloture ? out(avant) : '<div class="sous">(à la clôture)</div>';
  corps[6] = `<div style="display:flex;gap:8px;flex-wrap:wrap"><button class="btn" id="f-copie-contenu" title="Copie le récit pour le coller dans École Directe">${S.copieED && S.copieED[hh] && S.copieED[hh].contenu ? '✔ contenu copié' : 'Copier le contenu de séance'}</button><button class="btn" id="f-copie-travail" title="Copie le travail à faire en entier pour le coller dans École Directe">${S.copieED && S.copieED[hh] && S.copieED[hh].travail ? '✔ travail copié' : 'Copier le travail à faire'}</button><span id="f-copie-etat" style="color:var(--texte2);font-size:.85rem"></span></div>`;
  corps[7] = out(barre);
  const tete = `<div class="pp-tete"><b>${S.preparation ? 'Préparer le cahier de textes' : 'Fin de l\'heure'} — étape ${n} sur 7 : ${TITRES[n]}</b><span style="display:flex;gap:6px">${S.preparation ? '<button class="btn or" id="f-revenir" title="Te ramène à la diapo où la classe est restée, et dégèle le tableau — c\'est le seul geste qui dégèle">Revenir au cours</button>' : '<button class="btn" id="f-preparer" title="Gèle le tableau sur la diapo en cours, t\'emmène au cahier de textes et ouvre la préparation sous la diapo : tu prépares tout pendant que la classe travaille">Préparer le cahier de textes</button><button class="btn" id="f-fermer" title="Referme la colonne et reprend le cours ; rien n\'est fermé, tes choix restent">Reprendre le cours</button>'}</span></div>`;
  const fil = `<div class="pp-fil">${E.map(e => `<span class="${e.ok ? 'ok' : ''}${e.n === n ? ' ici' : ''}"></span>`).join('')}</div>`;
  const etape = `<div class="sec ouverte" data-sec="${n}"><div class="pp-quoi">${QUOI[n]}</div>${corps[n]}</div>`;
  const nav = `<div class="pp-nav"><span><button class="btn" id="f-precedente" ${n <= 1 ? 'disabled ' : ''}title="L\'étape précédente">◀ Étape précédente</button></span><button class="btn or" id="f-suivante" data-fleche="${Math.min(7, n + 1)}" ${n >= 7 ? 'disabled ' : ''}${et && !et.ok && !et.facultatif ? ' class="btn or grise"' : ''} title="${et && !et.ok ? 'L\'étape en cours n\'est pas faite — tu peux quand même passer à la suivante' : 'L\'étape suivante'}">Étape suivante ▶${n < 7 ? ' (' + TITRES[n + 1] + ')' : ''}</button></div>`;
  const liste = `<div class="pp-liste" title="La liste de contrôle : elle se coche toute seule ; un clic sur une ligne ouvre l\'étape">${E.map(e => `<div class="sec${e.n === n ? ' ouverte' : ''}${e.ok ? ' faite' : ''}" data-sec="${e.n}"><span class="ctl-l${e.ok ? ' ok' : ''}${ctl.prochaine && ctl.prochaine.n === e.n ? ' ici' : ''}" data-ctl="${e.n}" data-ouvre="${e.n}">${e.ok ? '✔' : (e.n === n ? '▶' : '○')} ${e.n} · ${esc(e.lib)}${e.facultatif ? ' <i>(facultatif)</i>' : ''}${e.n === 4 && !e.ok && !recitFinal ? ' — <i>à relire à la fin de l\'heure</i>' : ''}${e.ok && e.n !== n && resume[e.n] ? '<span class="okr">' + resume[e.n] + '</span>' : ''}</span></div>`).join('')}<div style="margin-top:6px;color:var(--sourd);font-size:.75rem">${nbF} étape${nbF > 1 ? 's' : ''} faite${nbF > 1 ? 's' : ''} sur 6${ctl.prochaine ? ' — c\'est là que tu en es : ' + ctl.prochaine.n : ''}</div></div>`;
  return `<div class="seq">${tete}<div class="pp"><div>${fil}${etape}${nav}</div>${liste}</div></div>`; }
"""
